def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def decorator(func):
        cache = _TTLCache(maxsize, ttl, timer)
        def wrapper(*args, **kwargs):
            if not typed:
                args = args + (func.__defaults__ if func.__defaults__ is not None else (),)
            key = _make_key(args, kwargs, typed)
            try:
                cache_hit, (value, expiration) = cache[key]
                if expiration is None or timer() < expiration:
                    return value
                else:
                    cache.pop(key)
            except KeyError:
                pass
            value = func(*args, **kwargs)
            cache[key] = (value, None if ttl is None else timer() + ttl)
            return value
        return wrapper
    return decorator

