def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    def wrapper(func):
        cache = {}

        def inner(*args, **kwargs):
            if typed:
                _args = tuple(type(arg) for arg in args)
                _kwargs = {type(k): type(v) for k, v in kwargs.items()}
            else:
                _args, _kwargs = args, kwargs

            if _args not in cache:
                cache[_args] = func(*args, **kwargs)

            cache = cache.pop(_args)

            if len(cache) == maxsize:
                cache.pop(next(cache.iterkeys()))

            return cache[args]

    return inner

def lfu_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = {}
        use_count = Counter()
        def wrapper(*args, **kwargs):
            if typed:
                key = args + tuple(kwargs)
            else:
                key = args
            if key not in cache:
                cache[key] = func(*args, **kwargs)
                use_count[key] = 0
            else:
                use_count[key] += 1
            return cache.get(key)
        def get_most_frequent():
            max_count = None
            most_frequent_key = None
            for key, count in use_count.items():
                if max_count and count >= max_count:
                    continue
                max_count = count
                most_frequent_key = key
            return most_frequent_key
        def get_least_frequent():
            min_count = None
            least_frequent_key = None
            for key, count in use_count.items():
                if min_count and count <= min_count:
                    continue
                min_count = count
                least_frequent_key = key
            return least_frequent_key
        def full_cache():
            return len(cache) >= maxsize
        def evict():
            least_frequent_key = get_least_frequent()
            del cache[least_frequent_key]
            del use_count[least_frequent_key]
        wrapper.get_most_frequent = get_most_frequent
        wrapper.get_least_frequent = get_least_frequent
        wrapper.full_cache = full_cache
        wrapper.evict = evict
        return wrapper
    return decorator

