def validate(self, inventory, extract_spec_version=False):

    if extract_spec_version:
        # If spec version is not available, then determine it from the inventory
        if not inventory.has_property("type") or inventory.type not in self.SPEC_VERSIONS:
            raise ValueError("Unable to determine specification version from 'inventory' value")
        spec_version = self.SPEC_VERSIONS[inventory.type]
    else:
        spec_version = self.spec_version

    # Validate the structure of the inventory against the spec_version
    for key in inventory.keys():
        if key not in self.ALLOWED_KEYS[spec_version]:
            raise ValueError(f"Invalid key '{key}' in inventory")

    # Validate the type of the inventory against the spec_version
    if not inventory.has_property("type") or inventory.type not in self.ALLOWED_TYPES[spec_version]:
        raise ValueError(f"Invalid type '{inventory.type}' in inventory")

    # Validate the version of the inventory against the spec_version
    if not inventory.has_property("version") or not self.version_is_valid(inventory.version, spec_version):
        raise ValueError(f"Invalid version '{inventory.version}' in inventory")

    # Validate the contents of the inventory
    for key, value in inventory.items():
        if key in self.SPECIFIC_KEYS and not self.SPECIFIC_KEYS[key](value, spec_version):
            raise ValueError(f"Invalid value '{value}' for key '{key}' in inventory")

    # Other validation checks
    self.validate_counts(inventory, spec_version)
    self.validate_items(inventory, spec_version)

