def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        namaste = get_namaste_content(path, b"0=*")
    except OCFLCodecError:
        return "error: could not read Namaste information"
    if not namaste:
        return "error: no Namaste information found"
    if namaste[0] == b"ocfl_1\x00":
        return "root"
    elif namaste[0] == b"ocfl_obj_1\x00":
        return "object"
    elif namaste[0] == b"ocfl_file_1\x00":
        return "file"
    else:
        return "error: unknown Namaste prefix"

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise ValueError("params must be a dictionary")
    if not isinstance(bug_ids, (list, tuple)):
        raise ValueError("bug_ids must be a list or tuple")
    for bug_id in bug_ids:
        params["ids"] = bug_id
        response = self.bzapi.query(params)
        if response["error"]:
            raise RuntimeError(response["message"])
        for bug in response["bugs"]:
            if bug["id"] == bug_id:
                # update the bug with the new parameters
                self.bzapi.update_bug(bug_id, params)
                return bug_id
    raise RuntimeError("No bug found with the specified parameters")

def deep_merge_nodes(nodes):
    # Create a dictionary to store the de-duplicated nodes
    merged_nodes = {}

    for node in nodes:
        # If the key for the current node does not exist in the merged dictionary
        if node[0].value not in merged_nodes:
            # Add the node to the merged dictionary
            merged_nodes[node[0].value] = node[1]
        else:
            # If the key already exists, deep merge the node values
            if isinstance(node[1], MappingNode):
                merged_nodes[node[0].value] = deep_merge_nodes([
                    (node[1].value[0][0], node[1].value[0][1])
                ])
            else:
                # If the value is not a MappingNode, the last occurrence wins
                merged_nodes[node[0].value] = node[1]

    return merged_nodes.items()

