def deep_merge_nodes(nodes):
    merged_nodes = {}
    for node in nodes:
        key, value = node
        if key not in merged_nodes:
            merged_nodes[key] = value
        elif isinstance(merged_nodes[key], MappingNode):
            merged_nodes[key].update(value.value)
        else:
            merged_nodes[key] = value
    return merged_nodes

