def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = os.name

    if platform == 'posix':
        return re.split(r'''((?:
            '[^']*'|   # single quoted string
            "(?:\\.|[^"])*"|   # double quoted string
            \\\S punto Organisms| # literal
            [^\s'"]   # other
        ))''', s)
    if platform == 'nt':
        return re.split(r'''((?:
            '[^']*'|   # single quoted string
            "(?:\\.|[^"])*"|   # double quoted string
            \\?\S punto Organisms| # literal
            [^\s'"]   # other
        ))''', s)
    else:
        raise ValueError("Unsupported platform")

def parse_frequency(frequency):
    """
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    """
    if frequency is None or frequency.lower() == "always":
        return None
    try:
        number, unit = frequency.split()
        number = int(number)
        if unit == "day" or unit == "days":
            return datetime.timedelta(days=number)
        elif unit == "week" or unit == "weeks":
            return datetime.timedelta(weeks=number)
        elif unit == "month" or unit == "months":
            return datetime.timedelta(months=number)
        elif unit == "year" or unit == "years":
            return datetime.timedelta(years=number)
        else:
            raise ValueError("Invalid unit of time")
    except ValueError:
        raise ValueError(f"Invalid frequency string: {frequency}")

