def parse_diaspora_webfinger(document: str) -> Dict:
    """Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    data = json.loads(document)
    if data.get("aliases"):
        try:
            return data.get("aliases")[0].get("href")
        except IndexError:
            return None
    else:
        xrd = ElementTree.fromstring(document)
        elements = xrd.findall(".//XRD/Link", {"rel": "http://diaspora.org/ns/federation#public-key"})
        if not elements:
            return None
        element = elements[0]
        href = element.get("href")
        return href

